#!/usr/bin/env python3
# luxarch:edit-history hook v3 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Before a session first changes a file, it searches LuxPM for that file: a hold on it lives there.

A red burn-down works one rule across many files, so the agent reaches each file knowing only the
red on it. It does not know the line is on hold. Typical holds: a fix waiting on an upstream
release, a site another agent is working on, an escalation that says not to port a sibling's
workaround. Agents went straight past such holds, and "fixed" reds by moving the code where the
rule no longer looked. Rule: FLEET-AGENT-CONDUCT-STANDARD, "Before you change code to clear a red".

Why LuxPM and not git. Measured on three fleet repos, 91-99% of tracked files have commits that
name issue keys, so a key list per file is noise. The held file that prompted this rule (an
`on_hold` escalation on a conftest) was never committed under its hold's key. Its 15 commits named
12 OTHER keys. A LuxPM search for the file's path found the hold as its first `on_hold` hit.

PreToolUse(Edit | Write | MultiEdit | NotebookEdit | Bash). The first change this session makes to
a tracked file is denied until the session has searched LuxPM for that file: a
`luxpm_list_issues(search=...)` or `luxpm_semantic_search(query=...)` whose term contains the file's
name. `luxpm-search-mark` records each term when the search returns. The denial names the search
to run, and shows the file's last 3 commits as context. A new file and anything outside the
checkout pass. So does every change when the session has no id, or its terms cannot be
remembered: a gate that waits for a record it can never see would lock the file forever.

A Bash command is judged on every file it writes, each relative path from every directory the
shell can be in when it writes (`write_dirs`). A `cd`/`pushd` to one literal directory, written as
its own command at the top level, moves the shell when the command after it runs only if it
succeeded: after `&&`, or after `|| exit`/`|| return` (`cd <scratch> && cat > Dockerfile` writes the
scratch Dockerfile only). After `;`, a newline, `||` or a pipe, the write is judged in both
directories. A `cd` the hook cannot place (a variable, `cd -`, `popd`, one inside a subshell, group
or condition is placed but kept beside where the shell was) and `env -C` make the directory
unknown: a relative path then matches every tracked file whose path ends in it. Three directories
are placed by fact (v3): a variable the command assigned a literal value at its top level, before
the `cd` and not under a condition (`S=/tmp/x; cd "$S"`), and that no loop, `read`, `mapfile`,
`printf -v`, `declare`/`local`/`export`, `+=` or `${X:=…}` has set since, with no `.`, `source`
or `eval` in between (either may set any variable); `cd -` and `popd`, which return to a
directory the shell already stood in; and `cd "$(mktemp -d …)"`, a directory made just then, which
holds no tracked file (a `..` out of it is still unknown). A shell body the command runs (`bash
-c`, `$(…)`) starts in every directory the outer command reached.

What it cannot check: that the agent read the results. An `on_hold` issue, another agent's
`in_progress` issue, or an open escalation covering the code is a hold, and the standard says
what to do with it. It reads text only, and every git call is bounded in time.

Nor can it see a file that a program writes by its own code: `python3 - <<'EOF'` with
`open("CHANGELOG.md", "w")` in the body, a script file, `make`. The command names no path. Which
files a program writes is not decidable from its text: the path can be computed (a variable, an
f-string, a glob), and the write can go through any API (`Path.write_text`, `shutil`, `os.replace`,
a library). A matcher for the literal `open("x", "w")` would catch that one spelling and read as
coverage of the rest. Only a comparison of the tree before and after the command sees such a write,
and it sees it after the fact.
"""

from __future__ import annotations

import os
import re
import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from _cmdtext import edited, executable_texts, expand, shell_steps
from _ledger import read_event, search_terms, session_id, terms_writable, tree_dir

_TOOLS = ("Edit", "Write", "MultiEdit", "NotebookEdit", "Bash")
_GIT_ERRORS = (OSError, subprocess.SubprocessError)
# bound to a name: an inline `except (A, B)` formats differently under py314 (PEP 758)
_PATH_ERRORS = (ValueError, OSError)


def _git(root: Path, *args: str) -> str | None:
    try:
        r = subprocess.run(
            ["git", "-C", str(root), *args],
            capture_output=True,
            text=True,
            timeout=4,
            check=False,
        )
    except _GIT_ERRORS:
        return None
    return r.stdout if r.returncode == 0 else None


def searched_for(rel: str, terms: list[str]) -> bool:
    """A recorded search term names this file: its name, or a path ending in it."""
    name = Path(rel).name.lower()
    return any(name in t.lower() for t in terms)


_ANY = "*"  # a directory the hook cannot name
_NEW = (
    "+"  # a directory made by this command (`mktemp -d`): no tracked file is under it
)
_BACK = "-"  # `cd -` / `popd`: a directory the shell already stood in
_ASSIGN = re.compile(r"^([A-Za-z_][A-Za-z0-9_]{0,80})=(.*)$", re.S)
_MKTEMP_DIR = re.compile(r"^\$\(mktemp(?:[ \t]+[\w./%+-]{1,200})*\)$")
_MOVES = ("cd", "pushd", "popd")
_TOP = ("", "&&", ";", "\n")  # a command after these is not inside a condition


def _moved(argv: list[str], here: str, values: dict[str, str]) -> str:
    """Where `cd <dir>` moves a shell standing at `here` ('' = where it started): a directory,
    `_NEW`, `_BACK`, or `_ANY`."""
    ops = [w for w in argv[1:] if w not in ("-L", "-P", "-e", "-@", "--")]
    if os.path.basename(argv[0]) == "popd" or ops == ["-"]:
        return _BACK
    if len(ops) != 1 or ops[0].startswith("-"):
        return _ANY
    if _MKTEMP_DIR.match(ops[0]):
        flags = ops[0][2:-1].split()[1:]
        made = any(
            f == "--directory" or (f[:1] == "-" and f[1:2] != "-" and "d" in f)
            for f in flags
        )
        return _NEW if made else _ANY
    op = expand(ops[0], values)
    if here in (_ANY, _NEW) or re.search(r"[$`~*?\[]", op):
        return _ANY
    return os.path.join(here, op) if here else op


def _chdir(words: list[str]) -> bool:
    """`env -C <dir>` / `--chdir`: the program runs in another directory."""
    env = [i for i, w in enumerate(words) if os.path.basename(w) == "env"]
    return bool(env) and any(
        w in ("-C", "--chdir") or w.startswith(("--chdir=", "-C"))
        for w in words[env[0] + 1 :]
    )


def write_dirs(cmd: str) -> list[tuple[str, frozenset[str]]]:
    """`(target, directories)` for each repo path the command writes: every directory ('' =
    where the shell started, `_ANY` = one the hook cannot name) the shell can be in there."""
    out: list[tuple[str, frozenset[str]]] = []
    reached = {""}
    for n, text in enumerate(executable_texts(cmd)):
        dirs = {""} if n == 0 else set(reached)
        stood = set(
            dirs
        )  # every directory the shell has stood in: where `cd -` can return
        values: dict[str, str] = {}
        steps = shell_steps(text)
        depth = 0
        for i, st in enumerate(steps):
            nxt = steps[i + 1] if i + 1 < len(steps) else None
            after = nxt.sep if nxt else ""
            if st.words and not st.argv:
                _assigned(st, depth, after, values)
            else:
                _rebound(st, values)
            here = dirs | {_ANY} if _chdir(st.words) else dirs
            out.extend((t, frozenset(here)) for t in st.writes)
            if st.argv and os.path.basename(st.argv[0]) in _MOVES:
                bails = (
                    after == "||"
                    and nxt is not None
                    and nxt.argv[:1] in (["exit"], ["return"])
                )
                top = (
                    st.masked.split()[:1] == [st.argv[0]]
                    and depth == 0
                    and st.sep in _TOP
                )
                moved: set[str] = set()
                for h in dirs:
                    to = _moved(st.argv, h, values)
                    moved |= set(stood) if to == _BACK else {to}
                dirs = moved if top and (after == "&&" or bails) else dirs | moved
                stood |= dirs
            depth += sum(st.masked.count(c) for c in "({") - sum(
                st.masked.count(c) for c in ")}"
            )
            reached |= dirs
    return out


def _assigned(st: object, depth: int, after: str, values: dict[str, str]) -> None:
    """Record `X=value` (or `export X=value`) when the shell surely runs it: at the top level, not
    after `&&`/`||` nor before `||`, with a literal value. Any other assignment makes X unknown."""
    words = [w for w in getattr(st, "words", []) if w not in ("export", "readonly")]
    sure = depth == 0 and getattr(st, "sep", "") in ("", ";", "\n") and after != "||"
    for w in words:
        for found in re.finditer(r"\$\{([A-Za-z_]\w{0,80}):?=", w):
            values.pop(found.group(1), None)
        if re.match(r"^[A-Za-z_]\w{0,80}\+=", w):
            values.pop(w.split("+=", 1)[0], None)
            continue
        m = _ASSIGN.match(w)
        if not m:
            continue
        val = expand(m.group(2), values)
        if sure and not re.search(r"[$`]", val):
            values[m.group(1)] = val
        else:
            values.pop(m.group(1), None)


# builtins and keywords that set a variable from what runs (a loop, a read, a format)
_SETTERS = {
    "for",
    "select",
    "read",
    "mapfile",
    "readarray",
    "printf",
    "declare",
    "typeset",
    "local",
    "export",
    "readonly",
    "getopts",
    "let",
    "unset",
}
_NAMED = re.compile(r"^([A-Za-z_][A-Za-z0-9_]{0,80})(?:=|$)")


def _rebound(st: object, values: dict[str, str]) -> None:
    """A step that sets variables at run time (`for S in …`, `read S`, `printf -v S`, `declare
    S=…`, an `export S=$(…)` the lexer split): every name it may set loses its known value."""
    words = list(getattr(st, "words", []))
    argv = list(getattr(st, "argv", []))
    heads = {words[0] if words else "", argv[0] if argv else ""}
    if heads & {".", "source", "eval"}:
        values.clear()  # a sourced file or an evaluated string may set any variable
        return
    for w in words:
        # `X+=…` appends, `${X:=…}` / `${X=…}` assigns while it expands
        for found in re.finditer(r"\$\{([A-Za-z_]\w{0,80}):?=", w):
            values.pop(found.group(1), None)
        appended = re.match(r"^([A-Za-z_]\w{0,80})\+=", w)
        if appended:
            values.pop(appended.group(1), None)
    if not (heads & _SETTERS):
        return
    for w in words[1:]:
        m = _NAMED.match(w)
        if m:
            values.pop(m.group(1), None)


def _anywhere(root: Path, target: str) -> list[Path]:
    """Every tracked file whose path is `target` or ends in `/<target>`."""
    tail = re.sub(r"^(?:\.\./)+", "", os.path.normpath(target))
    listed = _git(root, "ls-files", "-z") or ""
    return [
        root / r
        for r in listed.split("\0")
        if r and (r == tail or r.endswith("/" + tail))
    ]


def _targets(ev: dict[str, object]) -> list[Path]:
    """Every file the tool call writes, absolute: a relative path from each directory the shell
    can be in."""
    ti = ev.get("tool_input")
    cwd = Path(str(ev.get("cwd") or "") or tree_dir())
    if ev.get("tool_name") == "Bash" and isinstance(ti, dict):
        out: list[Path] = []
        for t, dirs in write_dirs(str(ti.get("command") or "")):
            if os.path.isabs(t):
                out.append(Path(t))
                continue
            out.extend(cwd / d / t for d in sorted(dirs) if d not in (_ANY, _NEW))
            # a new directory holds no tracked file, unless the path climbs out of it
            if _ANY in dirs or (_NEW in dirs and ".." in Path(t).parts):
                out.extend(_anywhere(tree_dir(), t))
        return out
    path, _old, _new = edited(ev)
    if not path and isinstance(ti, dict):
        path = str(ti.get("notebook_path") or "")
    return [cwd / path] if path else []


def _held_check(root: Path, p: Path, terms: list[str]) -> str | None:
    """The file's repo path when its first change waits for a search, else None."""
    try:
        rel = p.resolve().relative_to(root.resolve()).as_posix()
    except _PATH_ERRORS:
        return None  # outside the checkout: not this repo's code
    if searched_for(rel, terms):
        return None
    if _git(root, "ls-files", "--error-unmatch", "--", f":(literal){rel}") is None:
        return None  # untracked or new: nothing can be held on it yet
    return rel


def main() -> int:
    ev = read_event()
    if str(ev.get("tool_name") or "") not in _TOOLS:
        return 0
    targets = _targets(ev)
    if not targets or not session_id() or not terms_writable():
        return 0
    root, terms = tree_dir(), search_terms()
    rel = next((r for p in targets if (r := _held_check(root, p, terms))), None)
    if rel is None:
        return 0
    recent = (
        _git(root, "log", "-n3", "--format=  %h %cs %s", "--", f":(literal){rel}") or ""
    ).rstrip()
    print(
        f"HISTORY CHECK: search LuxPM for {rel} before your first change to it this session.\n"
        f'  luxpm_list_issues(search="{rel}")  (this repo\'s project; read every hit, not the titles)\n'
        "A hit that is on_hold, in_progress under another agent, or an open escalation covering this "
        "code means the site is HELD: do not change it. Name it in one line (key, file, why) and go on "
        "to the next red. A red moved to another file or out of a rule's sight is not a fix.\n"
        "Once the search has run, retry this edit: it passes.\n"
        + (f"Recent commits on it:\n{recent}\n" if recent else "")
        + 'See --doc FLEET-AGENT-CONDUCT-STANDARD, "Before you change code to clear a red".',
        file=sys.stderr,
    )
    return 2


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception:
        sys.exit(0)
